reproduction.script:
const fs=require('fs'),vm=require('vm'),assert=require('assert'),crypto=require('crypto');
const order=['prototype-core.js','prototype-reader.js','prototype-management.js','prototype-settings.js','prototype-product-r5.js','prototype-management-r5.js','prototype-settings-r5.js','prototype-context-r5.js','prototype-recovery-r5.js'];
const sources=Object.fromEntries(order.map(file=>[file,fs.readFileSync(file,'utf8')]));
const hashes=Object.fromEntries(order.map(file=>[file,crypto.createHash('sha256').update(sources[file]).digest('hex')]));
const noop=()=>{};
const els={};let document,bannerButton;let serial=0;
function element(name=''){
 const node={name,serial:++serial,id:'',textContent:'',dataset:{},children:[],childNodes:[],value:'',hidden:false,open:false,isConnected:true,
  classList:{add:noop,remove:noop,toggle:noop,contains:()=>false},style:{setProperty:noop},
  querySelector:()=>null,querySelectorAll:()=>[],setAttribute:noop,removeAttribute:noop,addEventListener:noop,
  appendChild:noop,prepend:noop,closest:()=>null,focus(){if(this.isConnected)document.activeElement=this;}};
 let html='';
 Object.defineProperty(node,'innerHTML',{get(){return html;},set(value){
  html=String(value);
  if(name==='banner'){
   if(bannerButton){bannerButton.isConnected=false;if(document.activeElement===bannerButton)document.activeElement=document.body;}
   const match=html.match(/data-action="([^"]+)"/);
   bannerButton=match?element('banner-button'):null;
   if(bannerButton)bannerButton.dataset.action=match[1];
  }
  if(name==='context'){
   if(els.noteInput){els.noteInput.isConnected=false;if(document.activeElement===els.noteInput)document.activeElement=document.body;delete els.noteInput;}
   if(/id=['"]noteInput['"]/.test(html)){els.noteInput=element('note-input');els.noteInput.id='noteInput';}
  }
 }});
 return node;
}
for(const id of ['screen','main','banner','context','appDialog','dialogBody','dialogTitle','dialogFooter','toast']){els[id]=element(id);els[id].id=id;}
els.banner.querySelector=selector=>selector==='button'?bannerButton:selector==='[data-action="recovery:notes"]'&&bannerButton?.dataset.action==='recovery:notes'?bannerButton:null;
const app=element('app'),body=element('body');
let oldToolbar=null;
document={getElementById:id=>els[id]||null,createElement:()=>Object.assign(element(),{content:{querySelector:()=>null}}),createTextNode:text=>({textContent:text,nodeType:3}),querySelector:selector=>selector==='.app'?app:null,
 querySelectorAll:selector=>selector==='[data-action]'?[bannerButton,oldToolbar].filter(node=>node?.isConnected):[],
 addEventListener:noop,documentElement:element('root'),body,activeElement:body};
const fragments=JSON.parse(fs.readFileSync('grok-fragments.json','utf8'));
for(const file of ['grok-product-r5.json','grok-management-r5.json','grok-settings-r5.json','grok-context-r5.json']){
 for(const edit of JSON.parse(fs.readFileSync(file,'utf8')).applied.fragmentEdits||[]){
  assert.strictEqual(fragments[edit.fragment].split(edit.oldText).length-1,1,'unique edit '+file);
  fragments[edit.fragment]=fragments[edit.fragment].replace(edit.oldText,edit.newText);
 }
}
const H={fragments};
const context={HR:H,window:{HR:H},document,innerWidth:390,console,setTimeout:()=>1,clearTimeout:noop,URL,Promise};
vm.createContext(context);
for(const file of order)vm.runInContext(sources[file],context,{filename:file});
const readerAction=H.readerAction;const notesCalls=[];
H.readerAction=function(action,button){
 if(action==='context:notes')notesCalls.push({button,wasConnected:!!button?.isConnected});
 return readerAction.apply(this,arguments);
};
const cases=[];
const check=(id,description,fn)=>{fn();cases.push({id,description,result:'PASS'});};
H.state.route='settings';H.state.setting='ai';H.render();
H.settingsChange('defaultSource','current');
H.state.questionDraft={text:'보존할 질문',captured:H.target(),quote:'보존할 인용',mode:'snapshot',answers:[]};
H.state.noteDrafts={'podway|v3|index':{text:'보존할 메모',baseline:'이전 메모',dirty:true,conflictResolved:false,target:H.target()}};
H.state.draft.body='<h2>보존할 게시 전 초안</h2>';H.state.draft.title='검토 중인 초안';
const baseline={question:JSON.stringify(H.state.questionDraft),notes:JSON.stringify(H.state.noteDrafts),draft:JSON.stringify(H.state.draft)};
function preserved(scenario){
 assert.strictEqual(H.state.scenario,scenario);
 assert.strictEqual(JSON.stringify(H.state.questionDraft),baseline.question);
 assert.strictEqual(JSON.stringify(H.state.noteDrafts),baseline.notes);
 assert.strictEqual(JSON.stringify(H.state.draft),baseline.draft);
 assert.strictEqual(H.state.settingsR5.drafts.ai.defaultSource,'current');
}
for(const [scenario,action,route,detail] of [['source','source','sources',null],['provider','provider','settings','ai'],['conflict','notes','reader','notes'],['partial','coverage','maintenance','coverage'],['stale','drafts','maintenance','drafts']]){
 check('recovery_'+action,'Recovery '+action+' reaches the intended destination and preserves scenario plus all captured drafts.',()=>{
  H.state.scenario=scenario;H.render();
  const previousButton=bannerButton;
  assert.strictEqual(H.coreAction('recovery:'+action),true);
  assert.strictEqual(H.state.route,route);
  if(route==='settings')assert.strictEqual(H.state.setting,detail);
  if(route==='maintenance')assert.strictEqual(H.state.report,detail);
  if(route==='sources')assert.strictEqual(H.state.projectId,H.doc().project);
  if(route==='reader'){
   assert.strictEqual(H.state.context,'notes');
   assert.strictEqual(document.activeElement,els.noteInput);
   assert.notStrictEqual(bannerButton,previousButton);
   assert.strictEqual(previousButton.isConnected,false);
   assert.strictEqual(notesCalls.at(-1).button,bannerButton);
   assert.strictEqual(notesCalls.at(-1).wasConnected,true);
   H.readerAction('context:close');
   assert.strictEqual(H.state.context,null);
   assert.strictEqual(document.activeElement,bannerButton);
  }
  preserved(scenario);
 });
}
check('notes_from_existing_panel','Opening recovery from an existing Ask panel records the new live banner opener and restores it on close.',()=>{
 H.state.scenario='conflict';H.go('reader');
 oldToolbar=element('old-toolbar');oldToolbar.dataset.action='context:ask';
 H.readerAction('context:ask',oldToolbar);
 assert.strictEqual(H.state.context,'ask');
 H.coreAction('recovery:notes');
 assert.strictEqual(document.activeElement,els.noteInput);
 assert.strictEqual(notesCalls.at(-1).button,bannerButton);
 assert.strictEqual(notesCalls.at(-1).wasConnected,true);
 H.readerAction('context:close');
 assert.strictEqual(document.activeElement,bannerButton);
 assert.notStrictEqual(document.activeElement,oldToolbar);
 preserved('conflict');
});
check('notes_close_after_render','Reader resolves the replacement banner button by action when a render occurs before panel close.',()=>{
 H.coreAction('recovery:notes');
 const recorded=notesCalls.at(-1).button;
 H.render();
 assert.notStrictEqual(bannerButton,recorded);
 assert.strictEqual(recorded.isConnected,false);
 H.readerAction('context:close');
 assert.strictEqual(document.activeElement,bannerButton);
 assert.strictEqual(bannerButton.isConnected,true);
 preserved('conflict');
});
check('notes_unavailable_document','A missing selected document keeps the Reader guard and does not open a notes panel after fallback to Library.',()=>{
 const count=notesCalls.length;
 H.state.docId='missing-for-test';
 H.coreAction('recovery:notes');
 assert.strictEqual(H.state.route,'library');
 assert.strictEqual(H.state.context,null);
 assert.strictEqual(notesCalls.length,count);
 preserved('conflict');
 H.state.docId='podway';
});
check('connect_guard_delegation','The later recovery wrapper still delegates to C and blocks go:reader before pairing approval.',()=>{
 H.state.route='connect';H.state.pair.status='waiting';H.state.scenario='session';
 const target=JSON.stringify(H.state.pair.returnTarget||null);
 assert.strictEqual(H.coreAction('go:reader'),true);
 assert.strictEqual(H.state.route,'connect');
 assert.strictEqual(H.state.pair.status,'waiting');
 assert.strictEqual(JSON.stringify(H.state.pair.returnTarget||null),target);
 preserved('session');
});
console.log(JSON.stringify({result:'PASS',node:process.version,testedAt:new Date().toISOString(),sourceOrder:order,sourceSHA256:hashes,tests:cases,scope:'Original nine modules with R5 fragment edits loaded in assembler order; actual Reader openContext/closeContext and all recovery actions execute against a bounded memory DOM.',limitations:['The memory DOM explicitly models banner replacement, focus and connected-element lookup; it is not a browser or a complete DOM implementation.','No real keyboard events, responsive geometry, browser focus trap, remote build, publish, purge or I/O action was exercised.']}));
